from roman import from_roman, _to_roman


class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(from_roman('XIV'), 14)

    def test_all_standard_values_round_trip(self):
        for n in range(1, 4000):
            self.assertEqual(from_roman(_to_roman(n)), n)

    def test_known_values(self):
        for s, n in [('I', 1), ('IV', 4), ('IX', 9), ('XL', 40), ('XC', 90),
                     ('CD', 400), ('CM', 900), ('MCMXCIV', 1994), ('MMMCMXCIX', 3999)]:
            self.assertEqual(from_roman(s), n)

