        for s in ['IIII', 'VX', 'IC', 'MMMM', 'xiv', '', 'VV', 'IL', 'XM', 'IIV',
                  'IXI', 'IVI', 'CMC', 'DD', 'LL', 'XXXX', 'VIV', 'ABC', 'X IV']:
            with self.assertRaises(ValueError, msg=s):
                from_roman(s)


if __name__ == '__main__':
    unittest.main()
